package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.domain.protocol.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.articles.JdbcEntityDedup;
import com.lianxibu.site.service.articles.EntityDedupService;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;

/** Actual EntityDedupService changes and actual v2 native receipt share one business writer. */
class EntityHeatBusinessProducerTest {
    GenerationJdbcStoreTest f;EntityDedupService business;
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){f=fixture();f.fixture();boolean h2=f.source instanceof org.h2.jdbcx.JdbcDataSource;String time=h2?"TIMESTAMP(6)":"DATETIME(6)",text=h2?"CLOB":"MEDIUMTEXT";
        for(String table:List.of("source_run_items","source_runs","analyzed_entities"))f.jdbc.execute("DROP TABLE IF EXISTS "+table);
        f.jdbc.execute("CREATE TABLE source_runs(id VARCHAR(64) PRIMARY KEY,business_date DATE)");f.jdbc.update("INSERT INTO source_runs VALUES('fictional-run','2026-01-01')");
        f.jdbc.execute("CREATE TABLE source_run_items(id VARCHAR(64) PRIMARY KEY,run_id VARCHAR(64),source_id VARCHAR(80),source_item_id VARCHAR(128),category VARCHAR(16),entity_id VARCHAR(64),terminal_state VARCHAR(16),state VARCHAR(32),projection_decision VARCHAR(16),effective_valid INT,revision BIGINT,counted_occurrence_key BINARY(32) UNIQUE,created_at "+time+",validity_revision BIGINT,is_new INT,dedup_json "+text+")");
        f.jdbc.execute("CREATE TABLE analyzed_entities(id VARCHAR(64) PRIMARY KEY,created_at "+time+",revision BIGINT,category VARCHAR(16),identity_key "+text+",identity_hash BINARY(32),title VARCHAR(512),summary "+text+",first_recorded_at "+time+",last_seen_at "+time+",first_seen_business_date DATE,last_occurrence_at "+time+",occurrence_count BIGINT,repeat_count BIGINT,analysis_state VARCHAR(32),analysis_generation BIGINT,aliases_json "+text+",legacy_flag INT,UNIQUE(category,identity_hash))");
        business=new EntityDedupService(new JdbcEntityDedup(f.source),f.writes,new EntityDecisionJdbcLog(new JdbcEntityDecisions(f.source),"fictional-owner",f.clock,new JdbcEntityHeatSnapshots(f.source)),f.clock);
    }
    void item(String id,String source,String key){f.jdbc.update("INSERT INTO source_run_items(id,run_id,source_id,source_item_id,category,terminal_state,state,projection_decision,effective_valid,revision,created_at,validity_revision) VALUES(?,'fictional-run',?,?,'news_tech','accepted','pending','initialized',1,0,?,0)",id,source,key,LocalDateTime.ofInstant(f.clock.instant().minusSeconds(1),ZoneOffset.UTC));}
    EntityDedupService.Automatic command(String id,String decision,String target){return new EntityDedupService.Automatic(id,0,decision,"news_tech","fictional-identity",target,target==null?List.of():List.of(target),"Fictional title","Fictional summary","Fictional business decision");}
    SharedWriteExecutor.ActionContext action(String key,String resource){return new SharedWriteExecutor.ActionContext(key,resource,null);}
    List<tools.jackson.databind.JsonNode> receipts(){return f.jdbc.query("SELECT action_payload FROM jobs WHERE target_type='entity_decision' ORDER BY id",(r,n)->CanonicalJson.parse(r.getString(1)));}
    EntityHeatSnapshot snapshot(String operation,String entity){var n=receipts().stream().filter(r->operation.equals(r.get("operation").asText())).reduce((a,b)->b).orElseThrow();for(var row:n.get("entity_heat_snapshots")){var value=EntityHeatSnapshot.read(JdbcFrozenInputs.canonical(row));if(value.entityId().equals(entity))return value;}throw new AssertionError("fictional touched entity absent");}
    @Test void ActualIndependentContributionAndRepeatedObservationFreezeNativeCountsWithoutDuplicateOccurrence(){
        item("fictional-one","fictional-source-a","fictional-key");var create=command("fictional-one","new",null);var original=business.applyAutomatic(create,action("fictional-create","fictional-entity"));assertEquals(1,original.occurrenceCount());assertEquals(1,snapshot("new","fictional-entity").occurrenceCount());
        item("fictional-repeat","fictional-source-a","fictional-key");var repeat=business.applyAutomatic(command("fictional-repeat","existing","fictional-entity"),action("fictional-repeat","fictional-unused"));assertFalse(repeat.newContribution());assertEquals(1,repeat.occurrenceCount());
        item("fictional-independent","fictional-source-b","fictional-key");var independent=business.applyAutomatic(command("fictional-independent","existing","fictional-entity"),action("fictional-independent","fictional-unused"));assertTrue(independent.newContribution());assertEquals(2,independent.occurrenceCount());assertEquals(3,receipts().size());assertEquals(2,f.jdbc.queryForObject("SELECT occurrence_count FROM analyzed_entities WHERE id='fictional-entity'",Long.class));assertEquals(original,business.applyAutomatic(create,action("fictional-create","fictional-entity")));assertEquals(3,receipts().size());assertEquals(1,snapshot("new","fictional-entity").occurrenceCount());for(var receipt:receipts())assertEquals("entity-decision-v2",receipt.get("schema_version").asText());
    }
    @Test void ActualSplitAndExclusionFreezeBothSidesAndNeverKeepOldAbsoluteCount(){
        item("fictional-one","fictional-source-a","fictional-one");business.applyAutomatic(command("fictional-one","new",null),action("fictional-create","fictional-entity"));item("fictional-two","fictional-source-b","fictional-two");business.applyAutomatic(command("fictional-two","existing","fictional-entity"),action("fictional-existing","fictional-unused"));
        var split=business.split("fictional-one",1,"fictional-split-identity","Fictional split",null,"Fictional manual split",action("fictional-split","fictional-split-entity"));assertEquals(1,split.occurrenceCount());assertEquals(1,snapshot("split","fictional-entity").occurrenceCount());assertEquals(1,snapshot("split","fictional-split-entity").occurrenceCount());assertEquals(2,receipts().stream().filter(r->"split".equals(r.get("operation").asText())).findFirst().orElseThrow().get("entity_heat_snapshots").size());
        var excluded=business.exclude("fictional-one",2,"Fictional manual exclusion",action("fictional-exclude","fictional-unused"));assertEquals(0,excluded.occurrenceCount());var empty=snapshot("exclude","fictional-split-entity");assertEquals(0,empty.occurrenceCount());assertNull(empty.firstSeenBusinessDate());assertEquals(1,f.jdbc.queryForObject("SELECT occurrence_count FROM analyzed_entities WHERE id='fictional-entity'",Long.class));
    }
    @Test void ActualCountAssignmentRollsBackWhenTheNativeV2ReceiptCannotPersist(){item("fictional-one","fictional-source-a","fictional-one");f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_reject_heat_receipt CHECK(target_type IS NULL OR target_type<>'entity_decision')");assertThrows(RuntimeException.class,()->business.applyAutomatic(command("fictional-one","new",null),action("fictional-create","fictional-entity")));assertEquals(0,f.jdbc.queryForObject("SELECT COUNT(*) FROM analyzed_entities",Integer.class));assertNull(f.jdbc.queryForObject("SELECT entity_id FROM source_run_items WHERE id='fictional-one'",String.class));assertEquals(0,f.jdbc.queryForObject("SELECT revision FROM source_run_items WHERE id='fictional-one'",Long.class));assertTrue(receipts().isEmpty());}
    @Test void ActualNativeEntityCreationUsesUtcMicrosecondsAcrossJvmZones(){var previous=TimeZone.getDefault();try{int n=0;for(String zone:List.of("UTC","Asia/Shanghai","Asia/Tokyo","America/New_York")){TimeZone.setDefault(TimeZone.getTimeZone(zone));String id="fictional-zone-"+n++;item(id,"fictional-source",id);var command=new EntityDedupService.Automatic(id,0,"new","news_tech",id,null,List.of(),"Fictional zone",null,"Fictional UTC event");String entity=id+"-entity";business.applyAutomatic(command,action(id,entity));var state=receipts().stream().flatMap(r->{var values=new ArrayList<EntityHeatSnapshot>();for(var value:r.get("entity_heat_snapshots"))values.add(EntityHeatSnapshot.read(JdbcFrozenInputs.canonical(value)));return values.stream();}).filter(s->s.entityId().equals(entity)).findFirst().orElseThrow();assertEquals(f.clock.instant().truncatedTo(java.time.temporal.ChronoUnit.MICROS),state.firstRecordedAt());assertEquals(1,state.occurrenceCount());}}finally{TimeZone.setDefault(previous);}}
}
